// Types that read and write themselves: a format's records and packed flag fields, read in one call
// (`try reader.read(LocalFileHeader.self)`). Written by hand, or generated by `BytesMacros`' `@BinaryRecord`
// and `@BitFields`.

/// A value read from bytes by its own initializer.
///
/// ```swift
/// struct Version: BinaryParsable {
///     var major: UInt8, minor: UInt8
///     init<Mode: BytesCursorMode>(parsing reader: inout GenericBytesReader<Mode>) throws(BytesError) {
///         major = try reader.read(UInt8.self)
///         minor = try reader.read(UInt8.self)
///     }
/// }
/// let version = try reader.read(Version.self)
/// ```
///
/// Generic over the cursor's mode, so one parser serves every kind of reader; each use is specialized.
///
/// The `@BinaryRecord` and `@BitFields` macros (the `BytesMacros` product) generate this conformance, with
/// ``BinaryWritable`` and ``FixedSizeBinary``, from a struct's properties.
public protocol BinaryParsable {
    /// Reads a value, consuming its bytes.
    ///
    /// - Parameter reader: The cursor, positioned at the value.
    /// - Throws: ``BytesError`` if the bytes aren't a valid value; what's consumed then is up to the type
    ///   (records generated by `@BinaryRecord` consume nothing).
    init<Mode: BytesCursorMode>(parsing reader: inout GenericBytesReader<Mode>) throws(BytesError)
}

/// A value that writes its own bytes.
public protocol BinaryWritable {
    /// Writes the value.
    ///
    /// - Parameter writer: The cursor to write at.
    /// - Throws: ``BytesError/insufficientCapacity`` if there isn't room.
    func write<Mode: BytesCursorMode>(to writer: inout GenericBytesWriter<Mode>) throws(BytesError)
}

/// A value that always takes the same number of bytes: a record of fixed fields, or packed flags. Records
/// made of them know their size as a constant, so they're read with one bounds check.
public protocol FixedSizeBinary {
    /// The value's size in bytes.
    static var byteCount: Int { get }
}

public extension GenericBytesReader {
    /// Reads a `T`, by its own initializer.
    ///
    /// - Parameter type: The type to read.
    /// - Returns: The value.
    /// - Throws: What `T`'s initializer throws.
    @inlinable @inline(__always)
    @_lifetime(self: copy self)
    mutating func read<T: BinaryParsable>(_ type: T.Type) throws(BytesError) -> T {
        try T(parsing: &self)
    }
}

public extension GenericBytesWriter {
    /// Writes `value`, by its own method.
    ///
    /// - Parameter value: The value to write.
    /// - Throws: What `value`'s `write(to:)` throws.
    @inlinable @inline(__always)
    @_lifetime(self: copy self)
    mutating func write<T: BinaryWritable>(_ value: T) throws(BytesError) {
        try value.write(to: &self)
    }
}
